package main

// ❌ OLD: string(buf) allocates and copies the whole buffer every call
// to preserve string immutability. In a parser that processes
// thousands of tokens per request, this is a major allocation source:
// each token string is a fresh heap allocation + memcpy.
func parseTokens(buf []byte) []string {
	var out []string
	for _, tok := range split(buf) {
		out = append(out, string(tok)) // ❌ OLD: alloc + copy per token
	}
	return out
}

// The resulting strings are immutable and safe, but the copy cost is
// real at high throughput.

package main

import "unsafe"

// ✅ NEW: unsafe.String builds a string header over the existing bytes
// — NO copy. The string shares memory with the source slice. This is
// only safe when:
//   1. the source slice outlives the string, and
//   2. the source is never mutated afterward (or the string is not
//      used after mutation).
func parseTokens(buf []byte) []string {
	var out []string
	for _, tok := range split(buf) {
		// ✅ NEW: zero-copy string from the token bytes
		tokStr := unsafe.String(&tok[0], len(tok))
		out = append(out, tokStr)
	}
	return out
}

// ⚠️ Safety contract: the returned strings reference the SAME backing
// array as the input buf. If the caller mutates buf after this returns,
// the strings change (and could be corrupted). Use this only where the
// source is immutable for the string's lifetime — e.g. converting a
// parser's immutable input window to strings for hashing/lookup only.
